import{_ as n,a as o,c as t,ac as s}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第一册：英语初阶 · 单元 5 语法总结","description":"L97–L120 规则、例句、易错点。","frontmatter":{"title":"第一册：英语初阶 · 单元 5 语法总结","description":"L97–L120 规则、例句、易错点。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","summary":"L97–L120 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 单元 5：转述、程度比较与过去先后","link":"/life/english/new-concept/book-1/unit-05/overview"},"next":{"text":"第一册：英语初阶 · 单元 5 单词与短语","link":"/life/english/new-concept/book-1/unit-05/vocabulary"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 单元 5：转述、程度比较与过去先后","link":"/life/english/new-concept/book-1/unit-05/overview"},"next":{"text":"第一册：英语初阶 · 单元 5 单词与短语","link":"/life/english/new-concept/book-1/unit-05/vocabulary"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-05/grammar.md","filePath":"life/english/new-concept/book-1/unit-05/grammar.md"}'),a={name:"life/english/new-concept/book-1/unit-05/grammar.md"};function r(i,e,h,l,p,g){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="第一册-英语初阶-·-单元-5-语法总结" tabindex="-1">第一册：英语初阶 · 单元 5 语法总结 <a class="header-anchor" href="#第一册-英语初阶-·-单元-5-语法总结" aria-label="Permalink to &quot;第一册：英语初阶 · 单元 5 语法总结&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/unit-05/overview">单元导读</a> · <a href="/life/english/new-concept/book-1/unit-05/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-1/unit-05/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-1/unit-05/review">单元复习与自测</a></p><h2 id="名词性物主代词" tabindex="-1">名词性物主代词 <a class="header-anchor" href="#名词性物主代词" aria-label="Permalink to &quot;名词性物主代词&quot;">​</a></h2><p>my/your/her/our/their 后面接名词；mine/yours/hers/ours/theirs 本身能代表“某人的东西”，后面不再接名词。his 两种用法同形。Whose is this case? 可答 It is mine。物主代词随拥有者变化，不随被拥有的东西变复数；两只箱子属于我仍用 mine。多个形容词修饰名词时，尺寸常在颜色前。</p><p><strong>L97 原创例句：</strong> The small green suitcase is mine.</p><p>那个绿色的小手提箱是我的。</p><p><strong>L98 原创例句：</strong> Are these keys yours or hers?</p><p>这些钥匙是你的还是她的？</p><p><strong>易错：</strong> 不能写 mine suitcase；名词前用 my，独立使用才用 mine。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-097">Lesson 97</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-098">Lesson 98</a></p><h2 id="现在时引述与宾语从句" tabindex="-1">现在时引述与宾语从句 <a class="header-anchor" href="#现在时引述与宾语从句" aria-label="Permalink to &quot;现在时引述与宾语从句&quot;">​</a></h2><p>say 后可以接 that 引导的内容从句，that 在口语中常省略。主句为一般现在时 says 时，从句根据实际时间选择时态，不自动变过去。tell 通常需要人作宾语，如 tells me that ...；say 不能直接接人作宾语说 say me。宾语从句内部保留陈述语序，即使它含疑问意义也不能随意倒装。</p><p><strong>L99 原创例句：</strong> Ben says that his ankle hurts.</p><p>本说他的脚踝疼。</p><p><strong>L100 原创例句：</strong> She tells me that the floor is wet.</p><p>她告诉我地板是湿的。</p><p><strong>易错：</strong> say me 应改为 tell me 或 say to me；不要把 say 与 tell 的宾语结构混用。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-099">Lesson 99</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-100">Lesson 100</a></p><h2 id="间接引语中的人称转换" tabindex="-1">间接引语中的人称转换 <a class="header-anchor" href="#间接引语中的人称转换" aria-label="Permalink to &quot;间接引语中的人称转换&quot;">​</a></h2><p>把别人第一人称的话转述出来时，应按实际身份转换 I、my、we 等代词，而不是固定一律变 he。主句 says 为现在时，从句可保留原来的时态；说话者的 I 如果指 Rita，转述可用 she。时间地点词是否改变取决于转述发生的时间和地点，不是见到间接引语就机械替换全部词。</p><p><strong>L101 原创例句：</strong> Rita says she is staying with her aunt.</p><p>丽塔说她正和姨妈住在一起。</p><p><strong>L102 原创例句：</strong> The boys say they will arrive tomorrow.</p><p>男孩们说他们明天到达。</p><p><strong>易错：</strong> 转述 Rita 的 my aunt 通常要变 her aunt，而不是保留成转述者的 my。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-101">Lesson 101</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-102">Lesson 102</a></p><h2 id="too-very-enough" tabindex="-1">too/very/enough <a class="header-anchor" href="#too-very-enough" aria-label="Permalink to &quot;too/very/enough&quot;">​</a></h2><p>very 只是加强程度，too 通常表示超过合适范围、带来困难；enough 表足够。enough 修饰形容词或副词时放后面，如 easy enough；修饰名词时放前面，如 enough time。too ... to ... 表太……而不能，形容词或副词后接不定式说明结果。不要把 very difficult 误解为一定无法完成。</p><p><strong>L103 原创例句：</strong> The instructions are clear enough to follow.</p><p>这些说明足够清楚，可以照着操作。</p><p><strong>L104 原创例句：</strong> This suitcase is too heavy for me to lift.</p><p>这个箱子太重了，我提不起来。</p><p><strong>易错：</strong> 形容词后用 enough；不要写 enough clear。too heavy 表示超出能承受范围，不只是“很重”。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-103">Lesson 103</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-104">Lesson 104</a></p><h2 id="动词-宾语-to-do" tabindex="-1">动词 + 宾语 + to do <a class="header-anchor" href="#动词-宾语-to-do" aria-label="Permalink to &quot;动词 + 宾语 + to do&quot;">​</a></h2><p>want、ask、tell 等动词可接宾语和不定式，表示希望或要求某人做某事：ask someone to check。宾语代词用 me/him/her/us/them，不用主格。否定不定式在 to 前加 not，如 tell him not to wait。want to do 是自己想做，want someone to do 是想让别人做，动作执行者不同。</p><p><strong>L105 原创例句：</strong> Please ask Leo to check the figures.</p><p>请让利奥检查这些数字。</p><p><strong>L106 原创例句：</strong> I told her not to send the draft yet.</p><p>我告诉她先不要发送草稿。</p><p><strong>易错：</strong> tell her not to send 与 tell her to not send 相比，本课采用常见的 not to；不要用 tell she。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-105">Lesson 105</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-106">Lesson 106</a></p><h2 id="形容词比较级" tabindex="-1">形容词比较级 <a class="header-anchor" href="#形容词比较级" aria-label="Permalink to &quot;形容词比较级&quot;">​</a></h2><p>比较两者时常用形容词比较级 + than。短形容词常加 er，如 tall→taller；辅音加 y 结尾通常变 y 为 i 再加 er，如 heavy→heavier；多音节形容词常用 more。than 后的比较对象应同类，例如 this bag 与 that one。不能同时使用 more 和 heavier。</p><p><strong>L107 原创例句：</strong> This backpack is lighter than that one.</p><p>这个背包比那个轻。</p><p><strong>L108 原创例句：</strong> The blue jacket is more expensive than the grey one.</p><p>蓝夹克比灰夹克贵。</p><p><strong>易错：</strong> 不能写 more lighter；lighter 本身已经是比较级。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-107">Lesson 107</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-108">Lesson 108</a></p><h2 id="much-many-的比较级" tabindex="-1">much/many 的比较级 <a class="header-anchor" href="#much-many-的比较级" aria-label="Permalink to &quot;much/many 的比较级&quot;">​</a></h2><p>much 与 many 的比较级都是 more；little 表不可数数量时比较级为 less；few 对应 fewer，用于可数复数。比较水量用 more/less water，比较杯子数量用 more/fewer cups。a little 也可修饰比较级，表示稍微，如 a little cheaper。many 与 much 的选择取决于名词可数性，不能根据中文“多”判断。</p><p><strong>L109 原创例句：</strong> This recipe needs less sugar than the old one.</p><p>这个配方需要的糖比旧配方少。</p><p><strong>L110 原创例句：</strong> We used fewer paper cups this week.</p><p>这周我们用了更少的纸杯。</p><p><strong>易错：</strong> 标准书面表达中，cups 可数复数用 fewer；sugar 不可数用 less。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-109">Lesson 109</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-110">Lesson 110</a></p><h2 id="形容词最高级" tabindex="-1">形容词最高级 <a class="header-anchor" href="#形容词最高级" aria-label="Permalink to &quot;形容词最高级&quot;">​</a></h2><p>在明确范围内比较三者或更多对象，常用 the + 最高级。短形容词常加 est，多音节常用 most。范围可用 in + 地点/群体或 of + 复数集合，如 the cheapest of the three。good 的比较级和最高级是 better、best。highest price 不等于 best choice，应把评价维度说清楚。</p><p><strong>L111 原创例句：</strong> This is the lightest laptop in the shop.</p><p>这是店里最轻的笔记本电脑。</p><p><strong>L112 原创例句：</strong> Of the three routes, this one is the most convenient.</p><p>三条路线中，这条最方便。</p><p><strong>易错：</strong> 通常最高级前有 the；不能写 the most lightest。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-111">Lesson 111</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-112">Lesson 112</a></p><h2 id="so-neither-简短附和" tabindex="-1">so/neither 简短附和 <a class="header-anchor" href="#so-neither-简短附和" aria-label="Permalink to &quot;so/neither 简短附和&quot;">​</a></h2><p>肯定附和用 So + 助动词或情态动词 + 主语，否定附和用 Neither + 助动词或情态动词 + 主语。I can swim 对应 So can I；I don&#39;t drive 对应 Neither do I。选择的助动词需匹配原句，不能全部用 am。none 表没有一个或一点，通常替代前文数量，不等于 not 这个副词。</p><p><strong>L113 原创例句：</strong> I enjoy hiking, and so does my sister.</p><p>我喜欢远足，我姐姐也喜欢。</p><p><strong>L114 原创例句：</strong> I cannot skate, and neither can Tom.</p><p>我不会滑冰，汤姆也不会。</p><p><strong>易错：</strong> 原句含 can，附和保留 can；不要回答 Neither am I 来对应 cannot skate。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-113">Lesson 113</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-114">Lesson 114</a></p><h2 id="复合不定代词" tabindex="-1">复合不定代词 <a class="header-anchor" href="#复合不定代词" aria-label="Permalink to &quot;复合不定代词&quot;">​</a></h2><p>someone、anyone、everyone、no one 指人，something、anything、everything、nothing 指事物。作主语时通常视作单数，后用 is/has 等。形容词修饰它们时放在后面，如 something useful。nothing 和 no one 已含否定意义，标准英语通常不再加 not。some/any 的选择仍要结合肯定、否定、请求等语境。</p><p><strong>L115 原创例句：</strong> Someone is waiting at the side door.</p><p>有人正在侧门等候。</p><p><strong>L116 原创例句：</strong> There is nothing unusual in the box.</p><p>盒子里没有什么异常的东西。</p><p><strong>易错：</strong> 不要写 someone are；也不要用 not nothing 表达普通的“没有什么”。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-115">Lesson 115</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-116">Lesson 116</a></p><h2 id="过去进行时" tabindex="-1">过去进行时 <a class="header-anchor" href="#过去进行时" aria-label="Permalink to &quot;过去进行时&quot;">​</a></h2><p>过去进行时由 was/were + 动词 ing 构成，常描绘过去某时的背景动作。一般过去时可表达期间发生的较短事件，如 was cooking when the phone rang。when 可以引出事件，while 常引出持续背景，但应看从句的实际意义，不能把两个词与某一种时态死绑。过去进行时不保证动作最终完成。</p><p><strong>L117 原创例句：</strong> I was making breakfast when the lights went out.</p><p>停电时我正在做早饭。</p><p><strong>L118 原创例句：</strong> They were waiting outside at eight yesterday.</p><p>昨天八点时他们正在外面等候。</p><p><strong>易错：</strong> 过去背景用 was/were，不用现在的 am/is/are；短事件不一定也要写进行时。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-117">Lesson 117</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-118">Lesson 118</a></p><h2 id="过去完成时" tabindex="-1">过去完成时 <a class="header-anchor" href="#过去完成时" aria-label="Permalink to &quot;过去完成时&quot;">​</a></h2><p>过去完成时由 had + 过去分词构成，表示相对于一个过去参照点更早发生的动作。需要有过去参照点，不能只因为动作很久以前就用 had done。By the time we arrived, the shop had closed 中到达是参照点，关门更早。时间顺序非常明确时一般过去时也可能足够，但本课用过去完成时突出先后。</p><p><strong>L119 原创例句：</strong> By the time we arrived, the museum had closed.</p><p>我们到达时，博物馆已经关门了。</p><p><strong>L120 原创例句：</strong> She had saved the file before the computer stopped.</p><p>电脑停止运行前她已经保存了文件。</p><p><strong>易错：</strong> 过去完成时必须相对于过去参照点；不要只因 yesterday 就任意加 had。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-119">Lesson 119</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-120">Lesson 120</a></p>',98)])])}const m=n(a,[["render",r]]);export{u as __pageData,m as default};
